 public static void main(String[] args)throws Exception{Map<String,byte[]> entries=new TreeMap<>();Set<String> changed=new TreeSet<>();try(ZipFile z=new ZipFile(args[0])){for(var it=z.entries();it.hasMoreElements();){var e=it.nextElement();byte[] b=z.getInputStream(e).readAllBytes();ClassNode c=null;if(e.getName().equals("ichttt/mods/firstaid/common/util/CommonUtils.class")){c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if(m.name.equals("killPlayer")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(new VarInsnNode(ALOAD,2));h.add(new MethodInsnNode(INVOKESTATIC,V,"preventDeath","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)Z",false));gate(m,h,RETURN);}}
 if(e.getName().equals("ichttt/mods/firstaid/common/EventHandler.class")){c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods){if(m.name.equals("onEntityInteract")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new MethodInsnNode(INVOKESTATIC,A,"interact","(Ljava/lang/Object;)Z",false));gate(m,h,RETURN);}if(m.name.equals("attemptSelfDefibrillator")){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;m.instructions.add(new VarInsnNode(ALOAD,0));m.instructions.add(new MethodInsnNode(INVOKESTATIC,A,"self","(Ljava/lang/Object;)V",false));m.instructions.add(new InsnNode(RETURN));}if(m.name.equals("tickRescueProgress")){m.instructions.clear();m.tryCatchBlocks.clear();m.localVariables=null;m.instructions.add(new InsnNode(RETURN));}if(m.name.equals("preHandleCustomPlayerDamage")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new VarInsnNode(ALOAD,1));h.add(new VarInsnNode(FLOAD,2));h.add(new MethodInsnNode(INVOKESTATIC,A,"damage","(Ljava/lang/Object;Ljava/lang/Object;F)Ljava/lang/Boolean;",false));h.add(new InsnNode(DUP));LabelNode old=new LabelNode();h.add(new JumpInsnNode(IFNULL,old));h.add(new InsnNode(ARETURN));h.add(old);h.add(new FrameNode(F_SAME1,0,null,1,new Object[]{"java/lang/Boolean"}));h.add(new InsnNode(POP));m.instructions.insert(h);}}MethodNode tick=new MethodNode(ACC_PUBLIC|ACC_STATIC,"zomboid$assistTick","(Lnet/neoforged/neoforge/event/tick/PlayerTickEvent$Post;)V",null,null);tick.visitAnnotation("Lnet/neoforged/bus/api/SubscribeEvent;",true).visitEnd();tick.instructions.add(new VarInsnNode(ALOAD,0));tick.instructions.add(new MethodInsnNode(INVOKESTATIC,A,"tick","(Ljava/lang/Object;)V",false));tick.instructions.add(new InsnNode(RETURN));c.methods.add(tick);}
 if(e.getName().equals("ichttt/mods/firstaid/common/damagesystem/PlayerDamageModel.class")){c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if(m.name.equals("updateMedicalState")){int hooks=0;for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof FieldInsnNode f&&f.getOpcode()==PUTFIELD&&f.name.equals("unconsciousTicks")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new MethodInsnNode(INVOKESTATIC,V,"nativeCountdown","(ILjava/lang/Object;)I",false));m.instructions.insertBefore(n,h);hooks++;}if(hooks!=1)throw new IllegalStateException("Native countdown hook missing");}for(MethodNode m:c.methods)if(m.name.equals("performCriticalRescue")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new MethodInsnNode(INVOKESTATIC,A,"allowed","(Ljava/lang/Object;)Z",false));h.add(new InsnNode(ICONST_1));h.add(new InsnNode(IXOR));gate(m,h,IRETURN);}}
 if(e.getName().equals("ichttt/mods/firstaid/fracture/Bleeding.class")){c=new ClassNode();new ClassReader(b).accept(c,0);for(MethodNode m:c.methods)if(m.desc.equals("(Lnet/neoforged/neoforge/event/tick/PlayerTickEvent$Post;)V")){InsnList h=new InsnList();h.add(new VarInsnNode(ALOAD,0));h.add(new MethodInsnNode(INVOKEVIRTUAL,"net/neoforged/neoforge/event/tick/PlayerTickEvent$Post","getEntity","()Lnet/minecraft/world/entity/player/Player;",false));h.add(new MethodInsnNode(INVOKESTATIC,A,"bleedingGrace","(Ljava/lang/Object;)Z",false));gate(m,h,RETURN);}}
 if(e.getName().equals("ichttt/mods/firstaid/client/ClientEventHandler.class")){c=new ClassNode();new ClassReader(b).accept(c,0);int hooks=0;for(MethodNode m:c.methods)if(m.name.equals("findInteractionPrompt")){boolean self=false;for(AbstractInsnNode n:m.instructions.toArray()){if(n instanceof FieldInsnNode f&&f.name.equals("SELF_DEFIB"))self=true;if(self&&n instanceof FieldInsnNode f&&f.name.equals("DEFIBRILLATOR_RESCUE_HOLD_TICKS")){m.instructions.set(n,new InsnNode(ICONST_1));hooks++;self=false;}}}if(hooks!=1)throw new IllegalStateException("Self defib client hold hook missing");}
 if(e.getName().equals("ichttt/mods/firstaid/client/StatusEffectLayer.class")){c=new ClassNode();new ClassReader(b).accept(c,0);int hooks=0;for(MethodNode m:c.methods)if(m.name.equals("render")){for(LocalVariableNode local:m.localVariables==null?java.util.List.<LocalVariableNode>of():m.localVariables)if(local.name.equals("timer")){for(AbstractInsnNode n:m.instructions.toArray())if(n instanceof VarInsnNode v&&v.getOpcode()==ASTORE&&v.var==local.index){InsnList h=new InsnList();h.add(new InsnNode(POP));h.add(new MethodInsnNode(INVOKESTATIC,"dev/zomboid/firstaid/RevivalHud","countdown","()Ljava/lang/Object;",false));h.add(new TypeInsnNode(CHECKCAST,"net/minecraft/network/chat/MutableComponent"));m.instructions.insertBefore(n,h);hooks++;}}}if(hooks!=1)throw new IllegalStateException("Timer label hook missing: "+hooks);}
 if(c!=null){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);b=w.toByteArray();verify(b);changed.add(e.getName());}entries.put(e.getName(),b);}}
 if(changed.size()!=6)throw new IllegalStateException(changed.toString());try(var paths=Files.walk(Path.of(args[2]))){for(Path p:paths.filter(p->p.toString().endsWith(".class")).toList()){byte[] b=Files.readAllBytes(p);verify(b);entries.put(Path.of(args[2]).relativize(p).toString(),b);}}try(ZipOutputStream out=new ZipOutputStream(Files.newOutputStream(Path.of(args[1])))){for(var e:entries.entrySet()){out.putNextEntry(new ZipEntry(e.getKey()));out.write(e.getValue());out.closeEntry();}}System.out.println("Verified death interception, rescue, damage and bleed grace hooks");}
